import { MakeLogicType, actions, kea, path, reducers, selectors } from 'kea'

import { DEFAULT_RECENT_SORT, TodayRecentSort } from '~/layout/today/todayRecentOrder'

import {
    DEFAULT_SPACE_FEED_FILTERS,
    DEFAULT_SPACE_FEED_TYPES,
    SpaceFeedFilters,
    SpaceFeedGrouping,
    SpaceFeedType,
    hasActiveSpaceFeedFilters,
} from './spaceFeedEntries'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface spaceFeedViewLogicValues {
    filters: SpaceFeedFilters
    filtersActive: boolean
    grouping: SpaceFeedGrouping
    sort: TodayRecentSort
    types: SpaceFeedType[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface spaceFeedViewLogicActions {
    clearFilters: () => {
        value: true
    }
    setFilters: (filters: SpaceFeedFilters) => {
        filters: SpaceFeedFilters
    }
    setGrouping: (grouping: SpaceFeedGrouping) => {
        grouping: SpaceFeedGrouping
    }
    setSort: (sort: TodayRecentSort) => {
        sort: TodayRecentSort
    }
    setTypes: (types: SpaceFeedType[]) => {
        types: SpaceFeedType[]
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface spaceFeedViewLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        filtersActive: (filters: SpaceFeedFilters) => boolean
    }
}

export type spaceFeedViewLogicType = MakeLogicType<
    spaceFeedViewLogicValues,
    spaceFeedViewLogicActions,
    Record<string, any>,
    spaceFeedViewLogicMeta
>

/** How a person likes to read space feeds. One choice for every space, like PostHog Desktop. */
export const spaceFeedViewLogic = kea<spaceFeedViewLogicType>([
    path(['products', 'tasks', 'spaces', 'spaceFeedViewLogic']),
    actions({
        setTypes: (types: SpaceFeedType[]) => ({ types }),
        setFilters: (filters: SpaceFeedFilters) => ({ filters }),
        clearFilters: true,
        setSort: (sort: TodayRecentSort) => ({ sort }),
        setGrouping: (grouping: SpaceFeedGrouping) => ({ grouping }),
    }),
    reducers({
        types: [
            DEFAULT_SPACE_FEED_TYPES,
            { persist: true },
            // At least one type stays on, so the feed never goes blank from the toggles alone.
            { setTypes: (state, { types }) => (types.length ? types : state) },
        ],
        filters: [
            DEFAULT_SPACE_FEED_FILTERS,
            { persist: true },
            { setFilters: (_, { filters }) => filters, clearFilters: () => DEFAULT_SPACE_FEED_FILTERS },
        ],
        sort: [DEFAULT_RECENT_SORT as TodayRecentSort, { persist: true }, { setSort: (_, { sort }) => sort }],
        grouping: ['date' as SpaceFeedGrouping, { persist: true }, { setGrouping: (_, { grouping }) => grouping }],
    }),
    selectors({
        filtersActive: [(s) => [s.filters], (filters: SpaceFeedFilters): boolean => hasActiveSpaceFeedFilters(filters)],
    }),
])
